import { Cart, Category, ErrorEvent, Identity, PartyIdentification } from '../events';
/**
Description: Checkout step in which the shopper reviews the cart before submitting the order.
*/
export type CheckoutReview = {
    events: Array<Cart | Identity | PartyIdentification | ErrorEvent>;
}

export class CheckoutReviewBuilder {

    private checkoutReview: CheckoutReview = {
        events: []
    }

    private cart!: Cart;
    private errorEvent!: ErrorEvent;
    private identity!: Identity;
    private partyIdentification!: PartyIdentification;

    public withCart(cart: Cart) : CheckoutReviewBuilder {
        this.cart = cart;
        return this;
    }
    public withErrorEvent(errorEvent: ErrorEvent) : CheckoutReviewBuilder {
        this.errorEvent = errorEvent;
        return this;
    }
    public withIdentity(identity: Identity) : CheckoutReviewBuilder {
        this.identity = identity;
        return this;
    }
    public withPartyIdentification(partyIdentification: PartyIdentification) : CheckoutReviewBuilder {
        this.partyIdentification = partyIdentification;
        return this;
    }

    public build() : CheckoutReview {
        if(this.cart) {
            this.checkoutReview.events.push(this.cart);
        }
        if(this.errorEvent) {
            this.checkoutReview.events.push(this.errorEvent);
        }
        if(this.identity) {
            this.checkoutReview.events.push(this.identity);
        }
        if(this.partyIdentification) {
            this.checkoutReview.events.push(this.partyIdentification);
        }

        return this.checkoutReview;
    }
}
